import { existsSync, outputJSONSync, readJSONSync } from 'fs-extra';
import { join } from 'path';
import { locateEmbroiderWorkingDir } from '@embroider/shared-internals';
import type { Options as ResolverOptions } from './module-resolver-options';

/**
 * The prebuild of `compatBuild` writes the resolver options here.
 * Users do not edit this file. Their options go in the Embroider config file.
 */
export function resolverConfigFile(appRoot: string): string {
  return join(locateEmbroiderWorkingDir(appRoot), 'resolver.json');
}

type SplitRouteConfigType = { type: 'string'; value: string } | { type: 'regex'; value: string };

export function writeResolverConfig(appRoot: string, config: ResolverOptions): void {
  outputJSONSync(
    resolverConfigFile(appRoot),
    {
      ...config,
      splitAtRoutes: config.splitAtRoutes?.map((s): SplitRouteConfigType => {
        if (typeof s === 'string') {
          return { type: 'string', value: s };
        }
        return { type: 'regex', value: s.toString() };
      }),
    },
    { spaces: 2 }
  );
}

export function readResolverConfig<T extends ResolverOptions = ResolverOptions>(appRoot: string): T | undefined {
  let file = resolverConfigFile(appRoot);
  if (!existsSync(file)) {
    return undefined;
  }
  let rawConfig = readJSONSync(file);
  rawConfig.splitAtRoutes = rawConfig.splitAtRoutes?.map((splitRouteConfig: SplitRouteConfigType) => {
    if (splitRouteConfig.type === 'regex') {
      const fragments = splitRouteConfig.value.match(/^\/(.*)\/([gimsuy]*)$/);
      if (!fragments) {
        throw new Error(`Unable to parse splitAtRoutes pattern ${splitRouteConfig.value}`);
      }
      const [, parsedPattern, parsedFlags] = fragments;
      return new RegExp(parsedPattern, parsedFlags);
    }
    return splitRouteConfig.value;
  });
  return rawConfig;
}
